def compute(vars):
    npm_adjustment_items = vars["v1"]
    operating_companies_income_increase = vars["v2"]

    if operating_companies_income_increase == 0:
        return None

    ratio = npm_adjustment_items / operating_companies_income_increase
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "npm_adjustment_items": npm_adjustment_items,
            "operating_companies_income_increase": operating_companies_income_increase,
            "ratio": ratio,
            "percentage": percentage,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percent"
            }
        }
    }
